package cldr

import (
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"testing"
	"time"
)

// golden is testdata/golden.json: the outputs of the Perl modules ported
// here, generated by conformance/perl/gen_cldr_golden.pl
type golden struct {
	Format []struct {
		Time []int             `json:"time"`
		Out  map[string]string `json:"out"`
	} `json:"format"`
	Parse []struct {
		Pattern string  `json:"pattern"`
		Value   string  `json:"value"`
		Result  *string `json:"result"`
	} `json:"parse"`
}

func loadGolden(t *testing.T) golden {
	t.Helper()
	data, err := os.ReadFile("testdata/golden.json")
	if err != nil {
		t.Fatal(err)
	}
	var g golden
	if err := json.Unmarshal(data, &g); err != nil {
		t.Fatal(err)
	}
	return g
}

// TestFormatGolden checks Format against DateTime format_cldr
func TestFormatGolden(t *testing.T) {
	g := loadGolden(t)
	if len(g.Format) == 0 {
		t.Fatal("no format cases")
	}
	for _, c := range g.Format {
		d := c.Time
		tm := time.Date(d[0], time.Month(d[1]), d[2], d[3], d[4], d[5], d[6], time.UTC)
		patterns := make([]string, 0, len(c.Out))
		for p := range c.Out {
			patterns = append(patterns, p)
		}
		sort.Strings(patterns)
		for _, p := range patterns {
			if got := Format(tm, p); got != c.Out[p] {
				t.Errorf("Format(%s, %q) = %q, want %q", tm.Format(time.RFC3339Nano), p, got, c.Out[p])
			}
		}
	}
}

// TestParseGolden checks Parse against DateTime::Format::CLDR
func TestParseGolden(t *testing.T) {
	g := loadGolden(t)
	if len(g.Parse) == 0 {
		t.Fatal("no parse cases")
	}
	for _, c := range g.Parse {
		tm, ok := Parse(c.Value, c.Pattern)
		var got *string
		if ok {
			s := fmt.Sprintf("%04d-%02d-%02dT%02d:%02d:%02d.%09d", tm.Year(), tm.Month(), tm.Day(),
				tm.Hour(), tm.Minute(), tm.Second(), tm.Nanosecond())
			got = &s
		}
		show := func(s *string) string {
			if s == nil {
				return "undef"
			}
			return *s
		}
		if show(got) != show(c.Result) {
			t.Errorf("Parse(%q, %q) = %s, want %s", c.Value, c.Pattern, show(got), show(c.Result))
		}
	}
}
